WITH valid AS (SELECT id, store_id, product_id, quantity, last_restock, DATE_ADD(last_restock, 51) AS last_restock_plus_51d, DATEDIFF(CURRENT_DATE(), last_restock) / 365 AS years_since_last_restock FROM inventory WHERE last_restock <= '2025-07-01'), latest AS (SELECT id, store_id, years_since_last_restock FROM (SELECT *, ROW_NUMBER() OVER (PARTITION BY store_id, product_id ORDER BY last_restock DESC, id) AS rank_in_group FROM valid) t WHERE rank_in_group = 1), base AS (SELECT *, CEIL(years_since_last_restock) AS years_since_last_restock_whole FROM latest WHERE store_id = 4), cleaned AS (SELECT *, GREATEST(years_since_last_restock, years_since_last_restock_whole) AS greatest_years_since_last_restock_years_since_last_restock_whole FROM base WHERE store_id IN (1, 6)) SELECT * FROM (SELECT id, store_id, greatest_years_since_last_restock_years_since_last_restock_whole, years_since_last_restock FROM cleaned) src UNPIVOT (metric_value FOR measure IN (greatest_years_since_last_restock_years_since_last_restock_whole, years_since_last_restock));
